cpp_io_using_seekg_to_reposition_the_inp.code:
std::ifstream file("data.dat");

// Absolute positioning (from beginning)
file.seekg(100);

// Relative positioning (forward from current)
file.seekg(20, std::ios::cur);

// Relative positioning (backward from end)
file.seekg(-10, std::ios::end);

// Save current position
std::streampos saved_pos = file.tellg();

// Restore position
file.seekg(saved_pos);

// seekg clears eofbit, sets failbit on error
if (file.fail()) {
    file.clear();
}
